(e=>{window.wu_dns_table=new Vue({el:"#wu-dns-table",data:{error:null,results:{},loading:!0},updated(){this.$nextTick(function(){window.wu_initialize_tooltip()})}}),e(document).ready(function(){e.ajax({url:ajaxurl,data:{action:"wu_get_dns_records",domain:wu_dns_table_config.domain,_ajax_nonce:wu_dns_table_config.nonce},success(e){Vue.set(window.wu_dns_table,"loading",!1),e.success?Vue.set(window.wu_dns_table,"results",e.data):Vue.set(window.wu_dns_table,"error",e.data)},error(e){Vue.set(window.wu_dns_table,"loading",!1),wu_ajax_error(e)}})})})(jQuery);